 auto s=subject();auto saved=store->append(s,QJsonObject{});check(saved==s,"first save empty baseline");auto s2=s;s2["id"]="s@2";s2["parentId"]="s@1";s2["displayName"]="修改名称";s2=store->append(s2,s);check(store->get("subjects","s@1")==s,"old subject retained");rejects([&]{auto stale=s2;stale["id"]="s@stale";store->append(stale,s);},"stale append rejected");auto m=method(s,source);check(m.value("assessment").toObject().value("status")=="fields_complete_not_validated","complete fields not validation");check(!m.value("assessment").toObject().value("authorConfirmed").toBool(),"no author confirmed");store->append(m,{});check(store->get("methods","m@1").value("subjectRef").toObject().value("originalRecord")==s,"saved subject snapshot not current rename");auto unquoted=m;unquoted["evidenceQuote"]="does-not-exist";unquoted=personMethod::seal(unquoted);check(unquoted.value("assessment").toObject().value("status")=="draft","unmatched quote draft");auto tampered=m;tampered["assessment"]=QJsonObject{{"methodValidated",true}};rejects([&]{personMethod::validate(tampered);},"confirmed method import rejected");auto bad=personMethod::version("person-method","sources",source.value("id").toString(),source);bad.remove("originalRecord");rejects([&]{personMethod::validateVersion(bad);},"bare ID ref rejected");auto staleBackup=store->backup();store->append(subject("other","other@1"),{});auto before=store->backup();rejects([&]{store->merge(decoded,staleBackup);},"stale preview transaction refused");check(store->backup()==before,"stale merge zero mutation");
 QJsonObject fixture=decoded;fixture["subjects"]=QJsonArray{s,s2};fixture["methods"]=QJsonArray{m};fixture["sources"]=QJsonArray{source};if(argc==3&&QString(argv[1])=="--export-fixture")write(QString::fromLocal8Bit(argv[2]),fixture);if(argc==3&&QString(argv[1])=="--check-fixture"){QFile f(QString::fromLocal8Bit(argv[2]));check(f.open(QIODevice::ReadOnly),"cross fixture open");auto java=personMethod::decode(f.readAll());check(java==fixture,"cross Java full version canonical JSON");}
 auto uiStore=std::make_shared<PersonMethodStore>(dir.filePath("ui.sqlite"));QJsonObject marker;{
 PersonMethodPage page(uiStore,[]{return QJsonArray{};},[](QJsonObject){});page.resize(1000,700);page.show();app.processEvents();page.findChild<QPlainTextEdit*>("pm_displayName")->setPlainText("首个对象");page.findChild<QPlainTextEdit*>("pm_platform")->setPlainText("人工记录");page.findChild<QPushButton*>("pmSave")->click();check(uiStore->backup().value("subjects").toArray().size()==1,"UI first-save baseline {} survives");page.findChild<QPlainTextEdit*>("pm_description")->setPlainText("未保存草稿");page.setDarkTheme(true);page.setDarkTheme(false);check(page.findChild<QPlainTextEdit*>("pm_description")->toPlainText()=="未保存草稿","theme preserves draft");page.findChild<QLineEdit*>("pmSearch")->setText("no-match");check(page.findChild<QPlainTextEdit*>("pm_description")->toPlainText()=="未保存草稿","filter preserves draft");marker=page.saveState();page.previewImport(personMethod::json(official()));check(uiStore->backup().value("subjects").toArray().size()==1,"UI preview not mutation");page.cancelImport();}
