 {QString wrong=dir.filePath("wrong.sqlite");auto name="wrong";auto db=QSqlDatabase::addDatabase("QSQLITE",name);db.setDatabaseName(wrong);check(db.open(),"wrong db opened");{QSqlQuery q(db);check(q.exec("CREATE TABLE protected(value TEXT)"),"wrong schema fixture");}db.close();db={};QSqlDatabase::removeDatabase(name);rejects([&]{PersonMethodStore untouched(wrong);},"reject non-library DB");}
